+/// Remove unused `ast-grep-ignore` directives from the file.
+///
+/// This is used in interactive/`--update-all` mode so that an unused
+/// suppression directive is fixed instead of only being reported.
+fn remove_unused_suppressions(
+  path: &Path,
+  matches: &[NodeMatch<StrDoc<SgLang>>],
+  file_content: &str,
+  printer: &impl Printer,
+) -> Result<()> {
+  if matches.is_empty() {
+    return Ok(());
+  }
+  // remove ranges from the end so earlier byte offsets stay valid
+  let mut ranges: Vec<_> = matches
+    .iter()
+    .map(|m| expand_to_line_whitespace(file_content, m.range()))
+    .collect();
+  ranges.sort_by_key(|r| std::cmp::Reverse(r.start));
+  // expanded ranges may overlap, only keep non-overlapping ones
+  ranges.dedup_by(|cur, next| {
+    let overlapped = cur.start < next.end;
+    if overlapped {
+      next.start = next.start.min(cur.start);
+      next.end = next.end.max(cur.end);
+    }
+    overlapped
+  });
+  let mut new_content = file_content.to_string();
+  for range in ranges {
+    new_content.replace_range(range, "");
+  }
+  if new_content == file_content {
+    return Ok(());
+  }
+  let diff = Diff {
+    node_match: matches[0].clone(),
+    replacement: Cow::Owned(new_content),
+    range: 0..file_content.len(),
+  };
+  let rule = unused_suppression_rule_config(&RuleOverwrite::default());
+  printer.print_rule_diffs(vec![(diff, &rule)], path)
+}
+
+/// Expand `range` to also swallow surrounding spaces/tabs when the directive
+/// occupies the whole line, so removing it does not leave a blank line.
+fn expand_to_line_whitespace(source: &str, range: Range<usize>) -> Range<usize> {
+  let is_space = |b: &u8| *b == b' ' || *b == b'\t';
+  let line_start = source[..range.start].rfind('\n').map_or(0, |i| i + 1);
+  let line_end = source[range.end..]
+    .find('\n')
+    .map_or(source.len(), |i| range.end + i);
+  let only_ws_before = source[line_start..range.start].bytes().all(|b| is_space(&b));
+  let only_ws_after = source[range.end..line_end].bytes().all(|b| is_space(&b));
+  if only_ws_before && only_ws_after {
+    // also eat the trailing line break so no empty line is left behind
+    let end = (line_end + 1).min(source.len());
+    line_start..end
+  } else {
+    range
+  }
